// Meta delivery status -> receipt Failed / Delivered / Read. Customer messages yahan nahi aate.
const out = [];
for (const item of $input.all()) {
  const root = item.json;
  for (const env of (Array.isArray(root) ? root : [root])) {
    const values = env.entry ? env.entry.flatMap(e => (e.changes || []).map(c => c.value)) : [env];
    for (const v of values) for (const s of (v?.statuses || [])) {
      if (!s.id || !['failed', 'delivered', 'read'].includes(s.status)) continue;
      const e = (s.errors || [])[0];
      out.push({ json: { metaId: s.id, status: s.status,
        error: e ? `Meta ${e.code}: ${e.error_data?.details || e.message || e.title || ''}`.trim() : '' } });
    }
  }
}
return out;
